/* ===================== v149.2: mapa — koła węzłów jako przeszkody dla podpisów =====================
   Po v149 podpis na telefonie mógł leżeć na kole węzła: napisy krypto na węźle Azji Płd.-Wsch., en 320 „Japan & Korea” na Bliskim Wschodzie,
   ja / zh 414 „+4.14%” na Indiach (w Chrome); ru 375 „−4,16%” Kanady tuż przy kole Europy. Teraz gLabBad liczy napis na tarczy (promień r,
   bez marginesu) jako kolizję, a gLabFit traktuje tarczę + 3 px jak przeszkodę, a odstęp do 8 px od cudzej tarczy — jako miejsce gorsze.
   Testy w piaskownicy v149Map (prawdziwe gLayout, labelSpotG, blok podpisów, słownik strony; atrapa measureText v149Ms). */
/* tarcze węzłów piaskownicy v149Map (gLabDiscs strony: regiony z r, krąg krypto) — używane też przez testy v149 */
function v149Discs(S) { return S.gLabDiscs(Object.keys(S.GLAY.N).map(k => S.GLAY.N[k]), S.CN); }
/* odległość pudełka b od tarczy c (ujemna — napis na tarczy) */
const v1492Gap = (b, c) => { const qx = Math.max(b[0], Math.min(c[0], b[2])), qy = Math.max(b[1], Math.min(c[1], b[3])); return Math.hypot(qx - c[0], qy - c[1]) - c[2]; };

test('v149.2: mapa — telefon 320 / 375 / 414 px w 10 językach: wartości z 03.10 — żaden napis na tarczy węzła ani kręgu krypto, poprawiony układ co najmniej 3 px od każdej tarczy; 8 zbiorów losowych (także z wielkimi węzłami) — napisów na tarczach wyraźnie mniej niż przed v149.2, w płótnie i bez nakładania', () => {
  const sets = [V149_F].concat([1, 2, 3, 4, 5, 6, 7, 8].map(v149Rand));
  let fit = 0, glow = 0, n = 0, on = 0, on0 = 0, f3 = 0, own8 = 0, ownN = 0;
  for (const [vw, W, H] of V149_PHONE) for (const L of V149_L10) sets.forEach((F, si) => {
    const S = v149Map(L, W, H, F), O = S.old(), R = S.run(), Dk = v149Discs(S), tag = L + ' ' + vw + ' zbiór ' + si;
    v149Check(S, R, tag);
    const all = R.r.concat(R.c), fitted = JSON.stringify(all) !== JSON.stringify(O), G = v149Groups(S, all, R.c.length);
    assert.equal(G.length, S.ord.length + 1, tag + ': podpis każdego węzła');
    const own = new Map(); G.forEach((g, i) => g.forEach(a => own.set(a, i < S.ord.length ? S.GLAY.N[S.ord[i].id] : null)));
    for (const a of all) {
      const b = S.gLabBox(a, v149Ms);
      for (const c of Dk) {
        const g = v1492Gap(b, c);
        if (si === 0) {
          assert.ok(g >= 0, tag + ': „' + a[0] + '” na tarczy węzła (' + c[0].toFixed(0) + ', ' + c[1].toFixed(0) + ', r ' + c[2].toFixed(1) + '): ' + g.toFixed(1) + ' px');
          if (fitted && !(c[3] === null && R.c.includes(a))) assert.ok(g >= 3 - 1e-9, tag + ': „' + a[0] + '” bliżej niż 3 px od tarczy: ' + g.toFixed(1));
        }
        if (g < 0) on++;
        if (fitted && c[3] !== own.get(a) && g < 8) glow++;   /* cudza tarcza bliżej niż 8 px */
        if (fitted && c[3] !== own.get(a) && c[3] !== null && !R.c.includes(a) && g < 3) f3++;   /* podpis regionu bliżej niż 3 px od cudzej tarczy */
      }
      n++;
    }
    /* ten sam zbiór w układzie v149 (gLabFit bez kół): napisy na tarczach — do porównania */
    for (const a of S.old()) for (const c of Dk) if (v1492Gap(S.gLabBox(a, v149Ms), c) < 0) on0++;
    if (fitted) fit++;
    /* podpis przy swoim węźle: w poprawionym układzie z danymi z 03.10 — tusz liter zwykle do 8 px od własnej tarczy */
    if (fitted && si === 0) G.slice(0, -1).forEach((g, i) => { const c = Dk.find(c => c[3] === S.GLAY.N[S.ord[i].id]); ownN++; if (Math.min(...g.map(a => v1492Gap(S.gLabBox(a, v149Ms), c))) < 8) own8++; });
  });
  assert.equal(f3, 0, 'podpis regionu bliżej niż 3 px od cudzej tarczy (także w zbiorach losowych)');
  assert.ok(own8 > ownN * .4, 'podpisy przy własnych węzłach: ' + own8 + ' z ' + ownN + ' do 8 px');
  assert.ok(fit > 60, 'układ poprawiany: ' + fit);
  assert.ok(on <= on0 / 20 && on < n * .002, 'napisy na tarczach: ' + on + ' (dotychczasowy układ: ' + on0 + ') z ' + n);
  assert.ok(glow < n * .03, 'napisy bliżej niż 8 px od cudzej tarczy — rzadko: ' + glow + ' z ' + n);
});

test('v149.2: mapa — przypadki z przeglądu: napisy krypto zeszły z tarczy Azji Płd.-Wsch. (zostają pod swoim kołem), podpis nie leży na cudzym węźle; dotychczasowy układ z napisem na tarczy jest wykrywany', () => {
  for (const [L, W, H] of [['ru', 345, 300], ['pl', 290, 300], ['en', 345, 300], ['ja', 384, 331], ['zh', 384, 331], ['de', 345, 300]]) {
    const S = v149Map(L, W, H, V149_F), O = S.old(), R = S.run(), Dk = v149Discs(S);
    const onDisc = A => A.filter(a => Dk.some(c => v1492Gap(S.gLabBox(a, v149Ms), c) < 0)).map(a => a[0]);
    const noDisc = S.gLabBad(v149Groups(S, O, 2), W, H, S.ov, v149Ms), withDisc = S.gLabBad(v149Groups(S, O, 2), W, H, S.ov, v149Ms, Dk);
    if (onDisc(O).length) assert.ok(withDisc, L + ' ' + W + ': napis na tarczy w dotychczasowym układzie wykryty: ' + onDisc(O));
    assert.ok(withDisc || !noDisc, L + ' ' + W + ': koła tylko dokładają kolizje');
    assert.deepEqual(onDisc(R.r.concat(R.c)), [], L + ' ' + W + ': bez napisów na tarczach');
    /* krypto: przy swoim kole — pod nim (niżej najwyżej o 40 px niż w v149), z lewej strony albo nad nim; wartość pod nazwą, wspólny środek */
    const [n0] = O.slice(-2), [n1, v1] = R.c, k = S.CN, dy = n1[2] - n0[2], bx = S.gLabBox(n1, v149Ms);
    assert.ok((dy >= 0 && dy <= 40 + 1e-9) || bx[2] <= k.x - k.r || v1[2] < k.y - k.r, L + ' ' + W + ': napisy krypto przy kole: ' + dy.toFixed(1));
    assert.ok(Math.hypot((bx[0] + bx[2]) / 2 - k.x, (bx[1] + bx[3]) / 2 - k.y) < k.r + 110, L + ' ' + W + ': napisy krypto blisko koła');
    assert.ok(Math.abs(v1[1] - n1[1]) < 1e-9 && v1[2] > n1[2], L + ' ' + W + ': wartość krypto pod nazwą, ten sam środek');
  }
  /* przegląd v149 (Chrome, ru 375): wartość Kanady przy kole Europy — w piaskownicy odstęp od cudzych tarcz w poprawionym układzie ≥ 3 px, zwykle ≥ 8 px */
  const S = v149Map('ru', 345, 300, V149_F), R = S.run(), Dk = v149Discs(S), eur = Dk.find(c => c[3] === S.GLAY.N.eur);
  for (const a of R.r) assert.ok(v1492Gap(S.gLabBox(a, v149Ms), eur) >= 3, 'ru 375: „' + a[0] + '” przy kole Europy');
});

test('v149.2: mapa — komputer (1186 × 576, 1400 × 600, 1100 × 520) w 10 językach: dotychczasowy układ bez napisu na tarczy, więc wynik dokładnie jak przed v149 (V149_OLD); najechanie na węzeł (większe koło) nie przełącza układu', () => {
  for (const L of V149_L10) for (const [W, H] of [[1186, 576], [1400, 600], [1100, 520]]) {
    const S = v149Map(L, W, H, V149_F), O = S.old(), Dk = v149Discs(S);
    assert.equal(S.gLabBad(v149Groups(S, O, 2), W, H, S.ov, v149Ms, Dk), false, L + ' ' + W + ': bez kolizji, także z kołami');
    assert.deepEqual(S.run().r.concat(S.run().c), O, L + ' ' + W + ': układ jak przed v149');
  }
  /* najechanie: _sr = 1,22 r — tarcze liczone z r, więc sprawdzenie bez zmian */
  const S = v149Map('pl', 1186, 576, V149_F), N = Object.keys(S.GLAY.N).map(k => S.GLAY.N[k]);
  const D0 = S.gLabDiscs(N, S.CN); N.forEach(m => { m._sr = m.r * 1.22; }); const D1 = S.gLabDiscs(N, S.CN);
  assert.deepEqual(D1.map(c => c.slice(0, 3)), D0.map(c => c.slice(0, 3)), 'tarcze z r, nie z _sr');
});

test('v149.2: gCirc, gLabDiscs i gLabBad z kołami — głębokość wejścia w koło, tarcze regionów i krypto, kolizja tylko przy prawdziwym nachodzeniu; kod: jedno wywołanie z kołami w gLabels', () => {
  const S = v149Map('pl', 345, 300, V149_F), A = ['Abc', 100, 50, '600 10.0px Sora,sans-serif', '#fff'], b = S.gLabBox(A, v149Ms);
  assert.equal(S.gCirc([0, 0, 10, 10], [20, 5], 5), 0, 'daleko'); assert.equal(S.gCirc([0, 0, 10, 10], [13, 5], 5), 2, 'bok: 2 px');
  assert.equal(S.gCirc([0, 0, 10, 10], [5, 5], 4), 4, 'środek w pudełku — cały promień'); assert.equal(S.gCirc([0, 0, 10, 10], [13, 14], 5), 0, 'róg: odległość 5');
  assert.ok(Math.abs(S.gCirc([0, 0, 10, 10], [13, 13], 5) - (5 - Math.hypot(3, 3))) < 1e-9, 'róg: odległość √18');
  const N = [{x: 10, y: 20, r: 7, _sr: 9}, {x: 40, y: 50, r: 8, _sr: 8}], D = S.gLabDiscs(N, {x: 300, y: 160, r: 15});
  assert.deepEqual(D.map(c => c.slice(0, 3)), [[10, 20, 7], [40, 50, 8], [300, 160, 15]]); assert.equal(D[0][3], N[0]); assert.equal(D[2][3], null);
  const cx = (b[0] + b[2]) / 2;
  assert.equal(S.gLabBad([[A]], 345, 300, [], v149Ms, [[cx, b[3] + 6, 5]]), false, 'koło 1 px pod napisem — bez kolizji (bez marginesu)');
  assert.equal(S.gLabBad([[A]], 345, 300, [], v149Ms, [[cx, b[3] + 4, 5]]), true, 'koło wchodzi w napis');
  assert.equal(S.gLabBad([[A]], 345, 300, [], v149Ms), false, 'bez kół — jak w v149');
  assert.equal(html.split('if(gLabBad(R.map(x=>x.t).concat([C.t]),W,H,ov||[],ms,gLabDiscs(N,CN)))gLabFit(R,C,CN,W,H,fz,ms,ov||[],N);').length, 2, 'gLabels: sprawdzenie z kołami');
  for (const f of ['function gCirc(b,c,R){', 'function gLabDiscs(N,CN){', 'function gLabBad(G,W,H,ov,ms,O){']) assert.equal(html.split(f).length, 2, f);
  /* gLabFit: tarcze twarde (+3 px) i miękkie (do 8 px od cudzej tarczy); krypto schodzi z cudzej tarczy */
  const f0 = html.indexOf('function gLabFit(R,C,CN,W,H,fz,ms,ov,nodes){'), F = html.slice(f0, html.indexOf('\n/* prostokąty elementów nad płótnem', f0));
  assert.ok(F.includes('gCirc(b,c,c[2]+3)*10') && F.includes('gCirc(b,c,c[2]+8)*4') && F.includes('D.reduce((q,c)=>q+gCirc(b,c,c[2]+3)*1000+(c[3]===null?0:gCirc(b,c,c[2]+8)*4),0)') && F.includes('tier===2?90:46'), 'gLabFit: koła jako przeszkody');
});

test('v149.2: gLabFit — napisy krypto schodzą z tarczy niżej, gdy wystarczy (ten sam środek); pamięć wyniku uwzględnia promień węzła', () => {
  const S = v149Map('pl', 345, 300, V149_F), CN = {x: 313, y: 168, r: 15.6}, f1 = '600 11px Sora,sans-serif', f2 = '600 10px Sora,sans-serif';
  const mk = () => ({vl: '+4,3 mld USD', t: [['Krypto', 313, 200.1, f1, '#fff'], ['+4,3 mld USD', 313, 213.6, f2, '#0f0']]});
  const w = Math.max(v149Ms('Krypto', f1).width, v149Ms('+4,3 mld USD', f2).width), cx = Math.min(313, 345 - w / 2 - 4);
  /* bez węzła pod napisami — jak w v149 (tylko przesunięcie do płótna) */
  const C0 = mk(); S.gLabFit([], C0, CN, 345, 300, S.fz, v149Ms, [], []);
  assert.deepEqual(C0.t.map(a => [a[1], a[2]]), [[cx, 200.1], [cx, 213.6]], 'bez kolizji — miejsce v149');
  /* mały węzeł tuż pod kołem krypto: napisy niżej o 2–14 px, ten sam środek */
  const C1 = mk(), nd = {x: cx, y: 187, r: 6, _sr: 6};
  S.gLabFit([], C1, CN, 345, 300, S.fz, v149Ms, [], [nd]);
  const dy = C1.t[0][2] - 200.1;
  assert.ok(C1.t[0][1] === cx && C1.t[1][1] === cx && dy >= 2 && dy <= 14 && Math.abs(C1.t[1][2] - 213.6 - dy) < 1e-9, 'niżej, ten sam środek: ' + JSON.stringify(C1.t.map(a => [a[1], a[2]])));
  for (const a of C1.t) assert.ok(v1492Gap(S.gLabBox(a, v149Ms), [nd.x, nd.y, nd.r]) >= 3, 'co najmniej 3 px od tarczy');
  /* pamięć: zmiana samego promienia r (bez _sr i położenia) — liczone od nowa */
  const r1 = S.run(), N = S.GLAY.N.asean, r0 = N.r; N.r = r0 * 1.5; const r2 = S.run(); N.r = r0;
  assert.notEqual(r2, r1, 'inny promień węzła — nowy wynik, nie z pamięci');
});

/* ===================== v150: tokenizowane aktywa — odczyt własny z łańcucha bloków (blok onchain w data/rwa.json), słownik EXTRA152 ===================== */
/* Plik RWA150_FILE (rwa_build na nagraniach v133 + udawany węzeł testów zbieracza; 04.10.2026 00:12 UTC; BUIDL, Paxos Gold i USYC w sumach z odczytu
   własnego, Tether Gold i reszta zamrożone). Blok v133 uruchamiany przez rw133.run (zegar przypięty, bez sieci). Klucze rwc.* — osobne od rwa.*
   (test v133 wymaga, by klucze rwa.* bloku były w słowniku v133). Testy nie zakładają, że słownik v150 jest ostatni (szukany po nazwie). */
const RWC150 = (() => {
  const clone = o => JSON.parse(JSON.stringify(o));
  const out = (F, l) => rw133.run(F, {real: true, lang: l || 'pl'}).el.innerHTML;
  const txt = h => h.replace(/<[^>]*>/g, '\n');
  return {clone, out, txt};
})();

test('v150: dzień 1 (pl) — kafle „w tym … z odczytu własnego ◆”, znak ◆ w tabeli produktów, akapit z czasem, regułami ceny i siecią bez adresu; zamrożone osobno', () => {
  const F = RWA150_FILE, o = RWC150.out(F), U = F.onchain.used;
  assert.deepEqual(Object.keys(U).sort(), ['blackrock-buidl', 'circle-usyc', 'paxos-gold'], 'trzy produkty w sumach z odczytu własnego');
  assert.ok(o.includes('Obligacje i fundusze — z bieżącą wyceną</span><b>' + rw133.run(F, {real: true}).K.rwUsd(F.seg.tb.v)), 'kafel główny: suma z odczytem własnym');
  assert.ok(o.includes('<small>w tym 4,7 mld USD z odczytu własnego z łańcucha ◆</small>'), 'kafel obligacji: część z odczytu własnego');
  assert.ok(o.includes('<small>w tym 6,5 mld USD z odczytu własnego z łańcucha ◆</small>') && o.includes('<small>w tym 1,8 mld USD z odczytu własnego z łańcucha ◆</small>'), 'kafle „razem” i „złoto”');
  assert.equal((o.match(/z odczytu własnego z łańcucha ◆<\/small>/g) || []).length, 3, 'kredyt prywatny bez linii (brak produktów z odczytu własnego)');
  assert.ok(/<p class="pnote">◆ Odczyt własny z łańcucha bloków \(stan na \[2026-10-04T00:12:00\+00:00\] · ago\(2026-10-04T00:12:00\+00:00\)\) — w sumach zamiast starych wartości: Circle USYC 2,4 mld USD, BlackRock BUIDL 2,3 mld USD, Paxos Gold 1,8 mld USD\. Wartość = liczba tokenów w obiegu \(kontrakty, których adres podaje emitent\) × cena\./.test(o), 'akapit: czas odczytu z wiekiem i produkty od największego (v163: zdanie metody)');
  assert.ok(o.includes('Fundusz o stałej wartości: 1 token = 1 USD (deklaracja emitenta).'), 'reguła 1 USD');
  assert.ok(o.includes('Złoto: 1 token = 1 uncja trojańska; cena złota 4140 USD za uncję z wyroczni cenowej na łańcuchu bloków ([2026-10-03T15:25:59+00:00]).'), 'reguła złota z ceną i czasem');
  assert.ok(o.includes('Fundusz o rosnącej wartości jednostki: cena jednostki z wyroczni funduszu na łańcuchu bloków — Circle USYC 1,1390 USD ([2026-10-02T12:31:59+00:00]).'), 'reguła wyroczni funduszu');
  assert.ok(o.includes('Circle USYC: sieci bez opublikowanego adresu kontraktu (Canton, NEAR; 03.10 ok. 0,06% jednostek wg emitenta) — tych tokenów nie liczymy.'), 'sieci bez adresu — opisane, nie zero');
  assert.ok(!o.includes('Bez pełnego odczytu'), 'wszystkie pełne — bez listy odczytów niepełnych');
  assert.ok(o.includes('<span class="rw-i">1.</span>Circle USYC ◆</span>') && o.includes('BlackRock BUIDL ◆</span>') && o.includes('Paxos Gold ◆</span>'), 'znak ◆ przy produktach z odczytu własnego');
  assert.ok(o.includes(' ◆ odczyt własny z łańcucha bloków (opis nad tabelami).'), 'objaśnienie znaku pod tabelą produktów');
  assert.ok(/Największe bez bieżącej wyceny \(poza tabelą i sumami\): Tether Gold 3,0 mld USD \(niezmieniona co najmniej od 27\.09\); Spiko/.test(o), 'zamrożone dalej osobno (Tether Gold pierwszy)');
  assert.ok(!/BlackRock BUIDL 3,5 mld|Circle USYC 2,6 mld|Paxos Gold 1,8 mld USD \(niezmieniona/.test(o), 'produkt z odczytu własnego nie jest już na liście zamrożonych (nigdy dwa razy)');
  assert.ok(o.includes('Odczyt własny liczy tokeny tylko w kontraktach, których adres publikuje emitent;'), '„Czego te dane nie mówią”: zdanie o odczycie własnym');
  assert.ok(!/NaN|undefined|null|rwc\.[a-z]/.test(RWC150.txt(o)), 'bez NaN i surowych kluczy');
});

test('v150: bez bloku, z wyłączonym blokiem i z odczytem niepełnym — strona jak v133 albo opis „bez pełnego odczytu”, nigdy zero', () => {
  const o133 = RWC150.out(RWA133_FILE);
  assert.ok(!o133.includes('◆') && !o133.includes('odczytu własnego') && !o133.includes('Odczyt własny'), 'plik bez bloku — nic z v150');
  const off = RWC150.clone(RWA150_FILE); off.onchain = {v: 1, off: true, at: off.at};
  const oo = RWC150.out(off);
  assert.ok(!oo.includes('odczytu własnego z łańcucha ◆') && !oo.includes('Odczyt własny z łańcucha bloków (stan'), 'wyłączony — bez linii i akapitu');
  const P = RWC150.clone(RWA150_FILE), b = P.onchain.p['blackrock-buidl'];
  delete P.onchain.used['blackrock-buidl']; b.nr = 9; b.v = null; b.full = false;
  P.onchain.seg.tb.v -= 2262224432; P.onchain.seg.all.v -= 2262224432;
  const g = P.onchain.p['paxos-gold']; delete P.onchain.used['paxos-gold']; g.px_ok = false; delete P.onchain.seg.cm; P.onchain.seg.all.v -= 1800961869;
  const op = RWC150.out(P);
  assert.ok(op.includes('Bez pełnego odczytu — zostają poza sumami: BlackRock BUIDL (odczytano 9 z 10 kontraktów); Paxos Gold (cena bez świeżego odczytu).'), 'odczyt niepełny i cena nieświeża opisane wprost');
  assert.ok(!op.includes('Złoto: 1 token') && !op.includes('Fundusz o stałej wartości'), 'reguły tylko dla produktów w sumach');
  assert.equal((op.match(/z odczytu własnego z łańcucha ◆<\/small>/g) || []).length, 2, 'kafel złota bez linii odczytu własnego');
  const E = RWC150.clone(RWA150_FILE); E.onchain.p['circle-usyc'].name = '<img src=x onerror=alert(1)>';
  assert.ok(!RWC150.out(E).includes('<img src=x') && RWC150.out(E).includes('&lt;img src=x onerror=alert(1)&gt; 2,4 mld USD'), 'nazwa produktu z pliku escapowana');
  const X = RWC150.clone(RWA150_FILE); X.onchain.p['circle-usyc'].bez_adresu = {sieci: ['Canton'], pct: null, dzien: 'zły'};
  assert.ok(RWC150.out(X).includes('(Canton; — ok. — jednostek wg emitenta)'), 'brak liczby — „—”, nigdy 0');
});

test('v150: słownik EXTRA152 — czysty JSON, jedna linia for po ostatniej (przy wstawieniu), 10 języków, te same klucze i pola, tłumaczenia; klucze bloku w słowniku', () => {
  const a = 'const EXTRA152=', x0 = html.indexOf(a);
  assert.ok(x0 > 0 && html.indexOf(a, x0 + 1) < 0, 'słownik dokładnie raz');
  const body = html.slice(x0 + a.length, html.indexOf(';\n', x0)), D = JSON.parse(body);
  assert.ok(html.includes(a + body + ';\nfor(const l in EXTRA152)if(I18N[l])Object.assign(I18N[l],EXTRA152[l]);\n'), 'czysty JSON + jedna linia nakładania');
  assert.equal((html.match(/EXTRA152/g) || []).length, 3, 'nazwa tylko w definicji i linii for');
  const L10 = ['pl', 'en', 'de', 'es', 'fr', 'it', 'pt', 'ru', 'zh', 'ja'], keys = Object.keys(D.pl), E = g126I18N();
  assert.deepEqual(Object.keys(D), L10); assert.ok(keys.length >= 10 && keys.every(k => k.startsWith('rwc.')), 'klucze rwc.*');
  const ph = s => (s.match(/\{[a-z0-9]+\}/g) || []).sort().join(',');
  for (const l of L10) {
    assert.deepEqual(Object.keys(D[l]), keys, l);
    for (const k of keys) {
      assert.ok(typeof D[l][k] === 'string' && D[l][k].trim(), l + ' ' + k); assert.equal(ph(D[l][k]), ph(D.pl[k]), 'pola ' + l + ' ' + k); assert.equal(E[l][k], D[l][k], 'nałożony ' + l + ' ' + k);
      if (l !== 'pl' && l !== 'en') assert.notEqual(D[l][k], D.en[k], l + ' ' + k + ': tłumaczenie');
      assert.ok(!/publicnode|1rpc|chainlink|aptos|solana|hashnote|coingecko|etherscan/i.test(D[l][k]), l + ' ' + k + ': bez nazw dostawców');
    }
  }
  for (const k of keys) assert.ok(!/(\d|\})[  　]+(営業日|日間|日|銘柄|件|か月|年|回|本|分|時間|週|つ|位|組|枚|取引日|ブロック|市場|契約)/.test(D.ja[k]), 'ja ' + k);
  const used = new Set([...rw133.BLK.matchAll(/t\('(rwc\.[a-z0-9.]+)'/g)].map(m => m[1]).filter(k => !['rwc.rez', 'rwc.rez0', 'rwc.zakres'].includes(k)));   /* v160/v161: klucze rezerwy i zakresu w EXTRA160/161 (tylko pl) */
  assert.deepEqual([...used].sort(), keys.slice().sort(), 'każdy klucz bloku w słowniku i każdy klucz słownika używany');
});

test('v150: panel z odczytem własnym w 10 językach — bez nazw dostawców, węzłów i wyroczni, bez surowych kluczy; ja bez spacji przed licznikiem; de / ja / en po swojemu', () => {
  for (const l of ['pl', 'en', 'de', 'es', 'fr', 'it', 'pt', 'ru', 'zh', 'ja']) {
    const o = RWC150.out(RWA150_FILE, l), t = RWC150.txt(o);
    assert.ok(!/de ?fi ?llama|llama\.fi|publicnode|1rpc|chainlink|aptoslabs|mainnet-beta|hashnote|tempo\.xyz|arc\.io/i.test(o), l + ': bez nazw dostawców');
    const bad = []; for (const s of t.split('\n')) { const h = G126_NAMES.check(s, l); if (h.length) bad.push(h[0]); }
    assert.deepEqual(bad, [], l + ': strażnik nazw');
    assert.ok(!/NaN|undefined|rwc\.[a-z]|rwa\.[a-z]/.test(t), l + ': bez surowych kluczy i NaN');
    assert.equal((o.match(/◆/g) || []).length, 3 + 1 + 3 + 1, l + ': znak w 3 kaflach, akapicie, 3 wierszach tabeli i objaśnieniu');
    if (l === 'ja') assert.ok(!/(\d|\})[  　]+(営業日|日間|日|銘柄|件|か月|年|回|本|分|時間|週|つ|位|組|枚|取引日|ブロック|市場|契約)/.test(t), 'ja: liczniki bez spacji');
  }
  const de = RWC150.out(RWA150_FILE, 'de'), en = RWC150.out(RWA150_FILE, 'en'), ja = RWC150.out(RWA150_FILE, 'ja');
  assert.ok(de.includes('davon 4,7 Mrd. USD aus eigener Blockchain-Abfrage ◆') && de.includes('Goldpreis 4.140 USD je Unze'), 'de: liczby po niemiecku');
  assert.ok(en.includes('incl. 4.7 B USD from our own blockchain reading ◆') && en.includes('gold price 4,140 USD per ounce'), 'en');
  assert.ok(ja.includes('1オンスあたり4,140米ドル') && ja.includes('◆ブロックチェーンの独自読み取り（') && ja.includes('持分の約0.06%'), 'ja: liczby i znak bez spacji przed „ブロック”');
});

/* ===================== v151: słowniki bez martwych kluczy =====================
   Przegląd v151 (plik roboczy wydania klucze_martwe.md): 150 kluczy, których kod strony nie czyta w żaden sposób — ani jako napis 'klucz' / "klucz" / `klucz`
   (t('…'), data-i18n="…", tablice kluczy), ani przez przedrostek lub końcówkę sklejane z wartością z kodu albo z plików danych ('g.n.'+id,
   `trd.s.${x}`, 'eng.x.'+widok+'.lim' …), ani przez I18N[LANG][k]. Wyjątek z dowodem: eng.x.<widok>.attr i eng.x.gen.attr czyta tylko engAttr(),
   której nic nie wywołuje. Usunięte ze wszystkich słowników i języków (1409 wpisów, 67 słowników); słowniki, które zostały bez wpisów (EXTRA9,
   EXTRA10, EXTRA12, a w pl / en EXTRA_SRV i EXTRA27), stoją dalej jako {} ze swoją linią for(…). Wiele usuniętych tekstów to dawne podpisy źródeł
   z nazwami dostawców i wydawców danych (zasada właściciela z 27.09: zero nazw na stronie — także w jej publicznym źródle). */
const V151_DEAD = [
  "bil.src", "bis2.src", "br.src", "cam.preset", "ceny.s.none", "ceny.s.srv", "cftc.src", "cftc.src.k",
  "cmc.mld", "cmc.src", "cof.src", "d.source", "eer.src", "eng.foot", "eng.k.rights", "eng.k.src",
  "eng.x.gen.attr", "eng.x.imf-portfolio-pairs.attr", "eng.x.wdi-destinations.attr", "etf.key.clear", "etf.key.hint", "etf.key.label", "etf.key.ph", "etf.key.save",
  "etf.meta", "etf.meta.errs", "etf.s.err", "etf.s.none", "etf.s.ok", "etf.s.srv", "g.cf.edge", "g.cov.sent",
  "g.help.2", "g.help.readd", "g.l.reg", "g.l.regtd", "g.leg.cry", "g.m.corrbis", "g.nodata1d", "g.plain.edge",
  "g.q.corrd", "g.q.corrv1", "g.q.covd", "g.q.freshd", "g.q.limd", "g.q.methd", "g.q.src", "g.q.srcd",
  "g.q.srcd2", "g.q.srcv", "g.src.reg", "g.src.reg1d", "g.src.regm", "g.src.regtd", "g.src.regtds", "g.src.regu",
  "global.d", "global.t", "hint2", "hint3", "howto.1", "howto.ok", "howto.t", "inst.bop.m",
  "inst.bop.src", "inst.ecb.src", "inst.fred.api", "inst.fred.src", "inst.mof.src", "inst.nyfed", "inst.tgb.src", "inst.usd.src",
  "kan.src", "key.cg.err", "key.cg.hint", "key.cg.label", "key.cg.none", "key.cg.ok", "key.fh.err", "key.fh.hint",
  "key.fh.label", "key.fh.none", "key.fh.ok", "key.fh.srv", "key.td.check", "key.td.hint", "key.td.label", "kor.src",
  "kpi.ageh", "kpi.agemin", "kpi.exch", "kpi.oi", "kr.not", "kr.src.cg", "kr.src.fng", "kr.sub",
  "leg.area", "mx.src", "nav.na", "ob.src", "pg.assets.d", "pg.fixed", "pg.no", "pg.ok",
  "q.lin", "q.lin.d", "q.lin.v", "q.src.d", "rail.relDesc", "rail.relLvl", "rez.src", "set.data",
  "sf.src", "sp.src", "spw.src", "th.src", "tic.m", "tic.src", "top.err.st", "top.score",
  "tr.src", "trd.foot", "trd.src.br", "trd.src.cf", "trd.src.cm", "trd.src.cs", "trd.src.etf", "trd.src.fe",
  "trd.src.fe.both", "trd.src.fe.ishares", "trd.src.fe.ssga", "trd.src.hk", "trd.src.in", "trd.src.jp", "trd.src.jpx", "trd.src.mx",
  "trd.src.stab", "trd.src.th", "trd.src.tr", "trd.src.tw", "trd.sub", "tv.foot", "ue.src", "view.net",
  "view.orbit", "wh.tx.open", "zr2.attr", "zr2.cz", "zr2.icons", "zr2.tv"];
/* wszystkie słowniki w kolejności nakładania: I18N, potem linie for(const l in …) — słowniki JSON przez JSON.parse, I18N / EXTRA / EXTRA2 jako literał JS */
function v151Dicts(src) {
  if (src === html && v151Dicts.c) return v151Dicts.c;
  const one = name => {
    const decl = 'const ' + name + '=', a = src.indexOf(decl), b = a + decl.length;
    assert.ok(a > 0 && src.indexOf(decl, a + 1) < 0, name + ': deklaracja dokładnie raz');
    if (src[b + 1] === '"') { const e = v143JsonEnd(src, b); return {name, json: true, obj: JSON.parse(src.slice(b, e))}; }
    return {name, json: false, obj: new Function('return ' + src.slice(b, src.indexOf('\n};', b) + 2) + ';')()};
  };
  const out = [one('I18N')].concat([...src.matchAll(/^for\(const l in (EXTRA\w*)\)(?:if\(I18N\[l\]\))?Object\.assign\(I18N\[l\],\1\[l\]\);?$/gm)].map(m => one(m[1])));
  if (src === html) v151Dicts.c = out;
  return out;
}
const v151Own = (o, k) => !!o && Object.prototype.hasOwnProperty.call(o, k);

test('v151: 150 usuniętych kluczy nie ma w żadnym słowniku ani języku (także I18N, EXTRA, EXTRA2); kod strony nie ma ich jako napisu ani atrybutu data-i18n; znacznik raz', () => {
  assert.equal(V151_DEAD.length, 150); assert.equal(new Set(V151_DEAD).size, 150);
  const D = v151Dicts(html);
  assert.ok(D.length >= 144 && D[0].name === 'I18N' && D.filter(d => !d.json).map(d => d.name).join() === 'I18N,EXTRA,EXTRA2', 'wszystkie słowniki, trzy nie-JSON');
  for (const d of D) for (const l in d.obj) for (const k of V151_DEAD) assert.ok(!v151Own(d.obj[l], k), d.name + ' ' + l + ': ' + k);
  const dic = html.slice(html.indexOf('const I18N={'), html.indexOf('/* ===================== STAN I DANE'));
  for (const k of V151_DEAD) assert.ok(!dic.includes('"' + k + '":') && !dic.includes("'" + k + "':"), 'tekst słowników: ' + k);
  const U = v143Usage(v143Code(html));
  for (const k of V151_DEAD) assert.ok(!U.lit.has(k), 'napis w kodzie strony: ' + k);
  for (const m of html.matchAll(/data-i18n(?:-[a-z]+)?="([^"]+)"/g)) assert.ok(!V151_DEAD.includes(m[1]), 'atrybut: ' + m[1]);
  /* usunięte klucze, które przybliżona reguła v143 (każdy przedrostek z kropką) formalnie obejmuje — z dowodem, że kod ich nie składa:
     eng.x.<widok>.attr i eng.x.gen.attr czyta tylko engAttr(), a jej nikt nie wywołuje; 'q.'+k tylko dla k z listy src / fresh / compl / meth */
  assert.deepEqual(V151_DEAD.filter(k => U.used(k)).sort(), ['eng.x.gen.attr', 'eng.x.imf-portfolio-pairs.attr', 'eng.x.wdi-destinations.attr', 'q.lin', 'q.lin.d', 'q.lin.v', 'q.src.d']);
  assert.ok(html.includes('function engAttr(rec){') && !/engAttr\(/.test(html.replace('function engAttr(', '')), 'engAttr bez wywołań');
  const code = v143Code(html);
  assert.equal(code.split("'q.'+").length, 2, 'jedno sklejanie z przedrostkiem q.'); assert.ok(code.includes("['src','fresh','compl','meth'].map(k=>`<div class=\"q\"><div class=\"t\">${t('q.'+k)}"), 'q.: tylko cztery karty');
  assert.ok(!/['"`]q\.(?:['"`]|\$\{)/.test(code.replace("t('q.'+k)", '')), 'q.: bez innego składania');
  assert.equal(html.split('/* v151: ze słowników usunięto klucze, których kod strony nie czyta').length, 2, 'znacznik v151 raz');
});

test('v151: słowniki po sprzątaniu — JSON dalej czystym JSON-em z jedną linią for, puste zostają jako {} (EXTRA9, EXTRA10, EXTRA12; EXTRA_SRV i EXTRA27 w pl / en); żaden język nie zniknął', () => {
  const D = v151Dicts(html), L10 = ['pl', 'en', 'de', 'es', 'fr', 'it', 'pt', 'ru', 'zh', 'ja'];
  for (const d of D.filter(x => x.json)) {
    const fl = new RegExp('^for\\(const l in ' + d.name + '\\)(?:if\\(I18N\\[l\\]\\))?Object\\.assign\\(I18N\\[l\\],' + d.name + '\\[l\\]\\);?$', 'gm'), a = html.indexOf('const ' + d.name + '=');
    assert.equal((html.match(fl) || []).length, 1, d.name + ': jedna linia nakładania');
    assert.ok(html.startsWith(';\nfor(const l in ' + d.name + ')', v143JsonEnd(html, a + d.name.length + 7)), d.name + ': linia zaraz po słowniku');
    for (const l in d.obj) assert.equal(Object.prototype.toString.call(d.obj[l]), '[object Object]', d.name + ' ' + l);
  }
  for (const n of ['EXTRA9', 'EXTRA10', 'EXTRA12']) { const d = D.find(x => x.name === n); assert.deepEqual(Object.keys(d.obj), L10, n); for (const l of L10) assert.deepEqual(d.obj[l], {}, n + ' ' + l); }
  for (const n of ['EXTRA_SRV', 'EXTRA27']) { const d = D.find(x => x.name === n); assert.deepEqual(d.obj, {pl: {}, en: {}}, n); }
  for (const n of ['I18N', 'EXTRA', 'EXTRA2']) assert.deepEqual(Object.keys(D.find(x => x.name === n).obj), L10, n + ': 10 języków');
  const I = v143Final(html);
  assert.deepEqual(Object.keys(I), L10); for (const l of L10) assert.ok(Object.keys(I[l]).length > 1500, l + ': ' + Object.keys(I[l]).length);
});

