/* ===================== v165: po przeglądzie wizualnym strony na żywo (04.10) ===================== */
function v165Blok() {
  const a = html.indexOf('/* ===================== v165: po przeglądzie wizualnym'), b = html.indexOf('/* v165: koniec bloku tabel i prawej kolumny */', a);
  assert.ok(a > 0 && b > a, 'blok v165');
  return new Function('$', html.slice(a, b) + '\nreturn {tblPrep, railPlace};')(() => null);
}
/* mini-DOM: element z atrybutami, klasami, colSpan i tekstem; tabela = nagłówek + wiersze (komórka [tekst, colSpan] albo tekst) */
function v165El(tag, txt = '', cs = 1) {
  const A = new Map(), C = new Set();
  return {tagName: tag, textContent: txt, colSpan: cs, A, C, setAttribute: (k, v) => { A.set(k, String(v)); }, getAttribute: k => (A.has(k) ? A.get(k) : null),
    classList: {add: c => { C.add(c); }, remove: c => { C.delete(c); }, contains: c => C.has(c)}};
}
function v165Tab(head, rows) {
  const tb = v165El('TABLE'), hr = Object.assign(v165El('TR'), {cells: head.map(h => v165El('TH', h))});
  tb.tHead = Object.assign(v165El('THEAD'), {rows: head.length ? [hr] : []});
  tb.tBodies = [Object.assign(v165El('TBODY'), {rows: rows.map(r => Object.assign(v165El('TR'), {cells: r.map(c => (Array.isArray(c) ? v165El('TD', c[0], c[1]) : v165El('TD', c)))}))})];
  return tb;
}
