/* mini-DOM z rodzicem i kolejnością dzieci */
function v165Node(id) {
  const C = new Set(), out = x => { const p = x.parentNode; if (p) { p.kids.splice(p.kids.indexOf(x), 1); x.parentNode = null; } };
  const n = {id, parentNode: null, kids: [], C, classList: {add: c => { C.add(c); }, remove: c => { C.delete(c); }, contains: c => C.has(c)},
    get nextSibling() { const p = this.parentNode; return p ? (p.kids[p.kids.indexOf(this) + 1] || null) : null; },
    insertBefore(x, ref) { out(x); const i = ref ? this.kids.indexOf(ref) : -1; this.kids.splice(i < 0 ? this.kids.length : i, 0, x); x.parentNode = this; return x; },
    after(x) { out(x); const p = this.parentNode; p.kids.splice(p.kids.indexOf(this) + 1, 0, x); x.parentNode = p; }};
  return n;
}
