  const M = {total_mcap: 2.915e12, mcap_chg24_pct: 0.18, btc_dom: 59.0, eth_dom: 11.3, btc_dom_y: 58.6, eth_dom_y: 11.4, total_mcap_y: 2.91e12, asof: 'A'};
