  assert.ok(Math.abs(o.alt.d - (alt - prev) / prev * 100) < 1e-9, 'kapitał poza: ' + o.alt.d); assert.equal(o.alt.d, p.alt.d, 'ceny na żywo nie zmieniają wyniku');
